'use strict';

/**
* Return the first index of an element in a double-precision floating-point strided array which is less than or equal to a specified search element.
*
* @module @stdlib/blas-ext-base-dindex-of-less-than-equal
*
* @example
* import Float64Array from '@stdlib/array-float64';
* import dindexOfLessThanEqual from '@stdlib/blas-ext-base-dindex-of-less-than-equal';
*
* var x = new Float64Array( [ 2.0, 3.0, 1.0, 4.0 ] );
*
* var idx = dindexOfLessThanEqual( x.length, 1.0, x, 1 );
* // returns 2
*
* @example
* import Float64Array from '@stdlib/array-float64';
* import dindexOfLessThanEqual from '@stdlib/blas-ext-base-dindex-of-less-than-equal';
*
* var x = new Float64Array( [ 2.0, 3.0, 1.0, 4.0 ] );
*
* var idx = dindexOfLessThanEqual.ndarray( x.length, 1.0, x, 1, 0 );
* // returns 2
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var dindexOfLessThanEqual;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dindexOfLessThanEqual = main;
} else {
	dindexOfLessThanEqual = tmp;
}


// EXPORTS //

export default dindexOfLessThanEqual;

// exports: { "ndarray": "dindexOfLessThanEqual.ndarray" }
